# -*- coding: utf-8 -*-
"""Compatibility shim for the standalone Kodi progressive runner.

The progressive RPC object is created in the JSON-RPC interpreter. Its native
Kodi window must not be moved to the long-lived Elementum service thread.
DialogSelect.show() already exposes the RPC object through the HTTP bridge and
starts kodi_progressive_runner.py with RunScript(). Therefore this module must
not monkey-patch DialogSelect.show() or the progressive RPC methods.
"""

from elementum.logger import log


_installed = False


def install_progressive_gui_dispatcher():
    global _installed
    if _installed:
        return

    _installed = True
    log.info(
        'Progressive GUI standalone-runner mode installed: '
        'DialogSelect.show is not intercepted'
    )


def process_pending_progressive_gui():
    # Kept for service.py compatibility. Native GUI work is owned by the
    # separate RunScript interpreter started by DialogSelect.show().
    return None
